import z3

def solve():
    # 11 vertices
    N = 11

    # Variables for edges
    edges = [[z3.Bool(f"e_{i}_{j}") for j in range(N)] for i in range(N)]

    # Variables for colors (0 or 1)
    colors = [z3.Int(f"c_{i}") for i in range(N)]

    solver = z3.Solver()

    # Colors are 0 or 1
    for i in range(N):
        solver.add(z3.Or(colors[i] == 0, colors[i] == 1))

    # Undirected graph, no self loops
    for i in range(N):
        solver.add(edges[i][i] == False)
        for j in range(i + 1, N):
            solver.add(edges[i][j] == edges[j][i])

    # Bipartite condition: if edge exists, colors must be different
    for i in range(N):
        for j in range(i + 1, N):
            solver.add(z3.Implies(edges[i][j], colors[i] != colors[j]))

    # Degree at least 3
    for i in range(N):
        degree = z3.Sum([z3.If(edges[i][j], 1, 0) for j in range(N)])
        solver.add(degree >= 3)

    # Known edges
    known_edges = [(1,10), (0,4), (0,8), (2,9)]
    for u, v in known_edges:
        solver.add(edges[u][v] == True)

    if solver.check() == z3.sat:
        m = solver.model()
        result = []
        for i in range(N):
            for j in range(i + 1, N):
                if z3.is_true(m[edges[i][j]]):
                    result.append((i, j))
        print(result)
    else:
        print("UNSATISFIABLE")

solve()
